-- Playbooks (S1: data, validated by the engine before it runs). mode on: the engine holds each row in measure for breach_doctor_playbook_cooldown_min (30) and demotes it after 2 failed cases in 24 h.
INSERT OR IGNORE INTO breach_playbooks (rule_id, version, family, cause_class, action_kind, trigger_sql, action_sql, revert_sql, verify_sql, min_ladder, max_per_tick, max_per_day, enabled, mode, note) VALUES
 ('MD-1', 1, 'METRIC-TRIGGER', 'metric-duplicate', 'sql', 'WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'' UNION ALL SELECT a.id AS issue_id, a.priority AS pri, (SELECT t.id FROM analytics_metric_triggers t WHERE t.enabled = 1 AND instr(lower(a.title), ''metric-trigger: '' || lower(t.metric_key)) = 1 ORDER BY length(t.metric_key) DESC, t.id DESC LIMIT 1) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger:'' AND lower(trim(a.title)) < ''metric-trigger:~''), d AS (SELECT tid, COUNT(*) AS n, MIN((CASE pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + issue_id) AS keep_key FROM oi WHERE tid IS NOT NULL AND tid > 0 GROUP BY tid HAVING COUNT(*) > 1) SELECT oi.issue_id AS issue_id, ''duplicate-trigger-issue'' AS subject, json_object(''trigger_id'', oi.tid, ''survivor_issue'', d.keep_key % 1000000000, ''open_issues'', d.n) AS facts_json FROM oi JOIN d ON d.tid = oi.tid WHERE (CASE oi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + oi.issue_id <> d.keep_key AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = oi.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host''))', json_array('WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'' UNION ALL SELECT a.id AS issue_id, a.priority AS pri, (SELECT t.id FROM analytics_metric_triggers t WHERE t.enabled = 1 AND instr(lower(a.title), ''metric-trigger: '' || lower(t.metric_key)) = 1 ORDER BY length(t.metric_key) DESC, t.id DESC LIMIT 1) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger:'' AND lower(trim(a.title)) < ''metric-trigger:~''), d AS (SELECT tid, COUNT(*) AS n, MIN((CASE pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + issue_id) AS keep_key FROM oi WHERE tid IS NOT NULL AND tid > 0 GROUP BY tid HAVING COUNT(*) > 1) INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT oi.issue_id, ''breach-doctor:MD-1'', ''closed'', ''breach-doctor'', datetime(''now''), ''SUPERSEDED BY #'' || (d.keep_key % 1000000000) || '': both issues are open for metric trigger '' || oi.tid || '' (a trigger whose title was edited files a second issue because the dedupe key is the whole title), and #'' || (d.keep_key % 1000000000) || '' keeps the highest priority and the lowest id and carries the work. Closed by breach-doctor rule MD-1 from agent_issues facts only.'' FROM oi JOIN d ON d.tid = oi.tid WHERE (CASE oi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) * 1000000000 + oi.issue_id <> d.keep_key AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = oi.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = oi.issue_id OR xw.path = ''issue:'' || oi.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND oi.issue_id = ?1 ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM issue_triage it JOIN agent_issues s ON s.id = CAST(substr(it.close_evidence, 16) AS INTEGER) WHERE it.issue_id = ?1 AND it.close_evidence LIKE ''SUPERSEDED BY #%'') THEN ''ok'' ELSE ''successor-missing'' END AS observed', 'delegated', 3, 12, 1, 'on', 'Duplicate open issue per trigger id (the whole-title dedupe of evaluateMetricTriggers files a second issue when a trigger title is edited; also a hand-filed ''METRIC-TRIGGER: <metric>'' beside the trigger''s own). Supersedes the loser to the survivor (highest priority, then lowest id) with SUPERSEDED BY #<id>. Live 2026-10-26 11:30Z: 0 hits (the three pairs 99924/100226, 99928/100225, 100088/1000015 were closed by hand since the audit; 532 rows read); seeded because the pair recurred three times in a week and the code prevention (MD-P1a) is a code-task. Revert reopens the loser.'),
 ('MD-4', 1, 'METRIC-TRIGGER', 'metric-recovered-open', 'sql', 'WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*''), cand AS (SELECT oi.issue_id AS issue_id, oi.tid AS tid, (SELECT MIN(l.fired_at) FROM analytics_action_log l WHERE l.trigger_id = oi.tid AND l.status = ''recovering'' AND l.id > COALESCE((SELECT MAX(f.id) FROM analytics_action_log f WHERE f.trigger_id = oi.tid AND f.status NOT IN (''recovering'',''recovered'')), 0)) AS streak_at FROM oi), st AS (SELECT cand.issue_id AS issue_id, cand.tid AS tid, cand.streak_at AS streak_at, s.val AS val, s.threshold AS thr FROM cand JOIN v_metric_trigger_state s ON s.id = cand.tid WHERE cand.streak_at IS NOT NULL AND (julianday(''now'') - julianday(cand.streak_at)) * 1440 >= 120 AND s.hit = 0 AND s.queue_target = ''agent_issues'') SELECT st.issue_id AS issue_id, ''recovered-open'' AS subject, json_object(''trigger_id'', st.tid, ''value'', st.val, ''threshold'', st.thr, ''clear_min'', CAST((julianday(''now'') - julianday(st.streak_at)) * 1440 AS INTEGER)) AS facts_json FROM st WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = st.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host''))', json_array('WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*''), cand AS (SELECT oi.issue_id AS issue_id, oi.tid AS tid, (SELECT MIN(l.fired_at) FROM analytics_action_log l WHERE l.trigger_id = oi.tid AND l.status = ''recovering'' AND l.id > COALESCE((SELECT MAX(f.id) FROM analytics_action_log f WHERE f.trigger_id = oi.tid AND f.status NOT IN (''recovering'',''recovered'')), 0)) AS streak_at FROM oi), st AS (SELECT cand.issue_id AS issue_id, cand.tid AS tid, cand.streak_at AS streak_at, s.val AS val, s.threshold AS thr FROM cand JOIN v_metric_trigger_state s ON s.id = cand.tid WHERE cand.streak_at IS NOT NULL AND (julianday(''now'') - julianday(cand.streak_at)) * 1440 >= 120 AND s.hit = 0 AND s.queue_target = ''agent_issues'') INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT st.issue_id, ''breach-doctor:MD-4'', ''closed'', ''breach-doctor'', datetime(''now''), ''TRIGGER-RECOVERY-1 second path: metric trigger '' || st.tid || '' reads clear, value '' || st.val || '' against threshold '' || st.thr || '', for '' || CAST((julianday(''now'') - julianday(st.streak_at)) * 1440 AS INTEGER) || '' minutes since its recovery streak opened with no relapse after it, and the evaluator had not closed issue '' || st.issue_id || ''. Closed by breach-doctor rule MD-4 from analytics_action_log and v_metric_trigger_state facts only.'' FROM st WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = st.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = st.issue_id OR xw.path = ''issue:'' || st.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND st.issue_id = ?1 ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM v_metric_trigger_state s WHERE s.id = (SELECT CAST(substr(x.title, 16, instr(substr(x.title, 16), ''-'') - 1) AS INTEGER) FROM agent_issues x WHERE x.id = ?1) AND s.hit = 1) THEN ''metric-hit-again'' ELSE ''ok'' END AS observed', 'delegated', 6, 24, 1, 'on', 'Recovered but open: the trigger reads clear, its recovery streak (the evaluator''s own ''recovering'' row after the last firing, analytics_action_log) is 120 minutes old with no relapse, and the evaluator has not closed the issue (second path of TRIGGER-RECOVERY-1 for the 06:20Z case, when 6 such issues sat open while the heartbeat was down). Closes with the reading, the threshold and the streak length as evidence. Live 2026-10-26 11:30Z: 0 hits (227 rows read): the evaluator is closing on its own again; this is the guard if it stops. Control metric-playbook-recovery-hold. Revert reopens.'),
 ('MD-6', 1, 'METRIC-TRIGGER', 'metric-covered-by-parent', 'sql', 'WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') SELECT c.issue_id AS issue_id, ''covered-by-parent'' AS subject, json_object(''child_trigger'', c.tid, ''parent_trigger'', pt.id, ''parent_issue'', MIN(pi.issue_id), ''parent_priority'', pi.pri, ''child_priority'', c.pri) AS facts_json FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = ''disabled-duplicate'' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 JOIN oi pi ON pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) WHERE NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = c.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) GROUP BY c.issue_id', json_array('WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT c.issue_id, ''breach-doctor:MD-6'', ''closed'', ''breach-doctor'', datetime(''now''), ''SUPERSEDED BY #'' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END)) || '': metric trigger '' || c.tid || '' is disabled (enabled=0) and metric_deps relation disabled-duplicate names metric '' || d.parent_metric || '' as the one that keeps its meaning, and the trigger '' || pt.id || '' of that metric is enabled and #'' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END)) || '' is open, at least as urgent and carries the work. Closed by breach-doctor rule MD-6 from analytics_metric_triggers, metric_deps and agent_issues facts only.'' FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = ''disabled-duplicate'' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 WHERE c.issue_id = ?1 AND (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN ''critical'' THEN 0 WHEN ''high'' THEN 1 WHEN ''medium'' THEN 2 ELSE 3 END)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = c.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = c.issue_id OR xw.path = ''issue:'' || c.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = ''closed'', owner = ''breach-doctor'', close_evidence = excluded.close_evidence'), json_array('UPDATE issue_triage SET triage_state = ''triaged'', close_evidence = NULL WHERE issue_id = ?1', 'UPDATE agent_issues SET status = ''open'', close_channel = NULL, updated_at = CAST(strftime(''%s'',''now'') AS INTEGER) * 1000 WHERE id = ?1 AND status = ''closed'''), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM agent_issues WHERE id = ?1 AND status IN (''closed'',''resolved'')) THEN ''issue-reopened'' WHEN EXISTS (SELECT 1 FROM issue_triage it JOIN agent_issues s ON s.id = CAST(substr(it.close_evidence, 16) AS INTEGER) WHERE it.issue_id = ?1 AND it.close_evidence LIKE ''SUPERSEDED BY #%'') THEN ''ok'' ELSE ''successor-missing'' END AS observed', 'delegated', 6, 24, 1, 'on', 'Covered by parent: a METRIC-TRIGGER issue whose trigger is disabled (enabled = 0) and whose metric has an active metric_deps row (relation disabled-duplicate, seeded from the BREACH-ONE-MEANING-1 notes) naming a metric whose trigger is enabled and has an open issue that is at least as urgent. Supersedes the child to the lowest-id such issue (SUPERSEDED BY #<id>). The 0.53.0 validator binds every statement to the one issue, so the playbook cannot raise a parent: the migration raised the parents of today''s children once (backup table bak_20261026_metric_playbooks_priority) and a child more urgent than its parent stays open, urgency is never dropped. Live 2026-10-26 11:30Z (1,503 rows read): 4 hits before the file raises the parents, 6 after (100225, 3015, 99914, 99915 reachable by the doctor, 99937 and 2570 carry a stale code-task line or a merged task, which the engine reads as a doer, so the migration closes those two once). A numeric-check relation (sum-of, ratio-of) needs its own playbook per relation and is not seeded.'),
 ('MD-7', 1, 'METRIC-TRIGGER', 'metric-time-gated', 'sql', 'WITH tk AS MATERIALIZED (SELECT f.ts AS ts, LAG(f.ts) OVER (ORDER BY f.ts) AS prev FROM fleet_tick f WHERE f.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-27 hours'')), gp AS (SELECT MAX(ts) AS gap_end FROM tk WHERE prev IS NOT NULL AND (julianday(ts) - julianday(prev)) * 1440 > 15), lt AS (SELECT MAX(ts) AS last_ts FROM tk), oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') SELECT oi.issue_id AS issue_id, ''time-gated'' AS subject, json_object(''trigger_id'', oi.tid, ''window_h'', 24, ''gap_end'', gp.gap_end, ''clears_by'', strftime(''%Y-%m-%dT%H:%M:%SZ'', gp.gap_end, ''+25 hours''), ''heartbeat_age_min'', CAST((julianday(''now'') - julianday(lt.last_ts)) * 1440 AS INTEGER)) AS facts_json FROM metric_deps d JOIN analytics_metric_triggers t ON t.metric_key = d.child_metric AND t.enabled = 1 JOIN oi ON oi.tid = t.id JOIN v_metric_trigger_state s ON s.id = t.id AND s.hit = 1 CROSS JOIN gp CROSS JOIN lt WHERE d.active = 1 AND d.relation = ''window-of-fleet-tick'' AND gp.gap_end IS NOT NULL AND gp.gap_end > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-24 hours'') AND (julianday(''now'') - julianday(lt.last_ts)) * 1440 <= 20 AND NOT EXISTS (SELECT 1 FROM metric_dispositions md WHERE md.issue_id = oi.issue_id AND md.kind = ''time-gated'' AND md.released_at IS NULL AND md.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = oi.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host''))', json_array('WITH tk AS MATERIALIZED (SELECT f.ts AS ts, LAG(f.ts) OVER (ORDER BY f.ts) AS prev FROM fleet_tick f WHERE f.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-27 hours'')), gp AS (SELECT MAX(ts) AS gap_end FROM tk WHERE prev IS NOT NULL AND (julianday(ts) - julianday(prev)) * 1440 > 15), lt AS (SELECT MAX(ts) AS last_ts FROM tk), oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') INSERT INTO metric_dispositions (metric, kind, issue_id, trigger_id, expires_at, evidence) SELECT t.metric_key, ''time-gated'', oi.issue_id, oi.tid, strftime(''%Y-%m-%dT%H:%M:%SZ'', gp.gap_end, ''+25 hours''), ''the last fleet_tick gap ended '' || gp.gap_end || '' and the heartbeat has run every slot since, and the 24 h window of metric trigger '' || oi.tid || '' holds the gap until 24 h after it, so the reading clears by the expiry (25 h) with no change. Rule MD-7 from fleet_tick and v_metric_trigger_state facts only.'' FROM metric_deps d JOIN analytics_metric_triggers t ON t.metric_key = d.child_metric AND t.enabled = 1 JOIN oi ON oi.tid = t.id JOIN v_metric_trigger_state s ON s.id = t.id AND s.hit = 1 CROSS JOIN gp CROSS JOIN lt WHERE d.active = 1 AND d.relation = ''window-of-fleet-tick'' AND gp.gap_end IS NOT NULL AND gp.gap_end > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-24 hours'') AND (julianday(''now'') - julianday(lt.last_ts)) * 1440 <= 20 AND NOT EXISTS (SELECT 1 FROM metric_dispositions md WHERE md.issue_id = oi.issue_id AND md.kind = ''time-gated'' AND md.released_at IS NULL AND md.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = oi.issue_id AND xc.status IN (''active'',''holding'') AND COALESCE(xc.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = oi.issue_id OR xw.path = ''issue:'' || oi.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) AND oi.issue_id = ?1'), json_array('UPDATE metric_dispositions SET released_at = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') WHERE issue_id = ?1 AND kind = ''time-gated'' AND released_at IS NULL'), 'SELECT ''ok'' AS expected, CASE WHEN NOT EXISTS (SELECT 1 FROM metric_dispositions WHERE issue_id = ?1 AND kind = ''time-gated'' AND released_at IS NULL AND expires_at > strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'')) THEN ''no-live-disposition'' WHEN (SELECT (julianday(''now'') - julianday(MAX(ts))) * 1440 FROM fleet_tick) > 20 THEN ''heartbeat-stale'' ELSE ''ok'' END AS observed', 'delegated', 3, 6, 1, 'on', 'Time-gated heartbeat metric: tick_completion_24h, tick_slot_coverage_24h and tick_sequence_completion_24h read the 24 h window of fleet_tick. Replay: the newest gap above 15 minutes in fleet_tick ended at G, the heartbeat has run every slot since (newest tick under 20 minutes old) and G is still inside the window, so the reading clears when G leaves it; the row in metric_dispositions expires 25 hours after G (a margin of an hour) and the issue stays open (no silent drop). Live 2026-10-26 11:30Z: 3 hits (2875, 99936, 2861, 1,948 rows read), G = 2026-10-26T06:06:58Z, expiry 2026-10-27T07:06:58Z. fm-metric-disposition-expired reads an expired row whose trigger is still hit. Revert releases the row.');

-- ONE-TIME: raise each parent issue of a covered child to the most urgent priority among its children. bak_20261026_metric_playbooks_priority keeps the previous priorities (the Rollback restores them).
-- The playbook MD-6 then supersedes a child only into a parent at least as urgent, so no urgency is lost: 99938 becomes critical (child 100225, trigger 409), 100301 high (child 99915), 99935 stays medium.
CREATE TABLE IF NOT EXISTS bak_20261026_metric_playbooks_priority AS
WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), '-') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = 'open' AND lower(trim(a.title)) >= 'metric-trigger-' AND lower(trim(a.title)) < 'metric-trigger.' AND a.title GLOB 'METRIC-TRIGGER-[0-9]*')
SELECT a.id AS id, a.priority AS priority FROM agent_issues a WHERE a.id IN (SELECT pi.issue_id FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = 'disabled-duplicate' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 JOIN oi pi ON pi.tid = pt.id AND pi.issue_id <> c.issue_id);

WITH oi AS MATERIALIZED (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), '-') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = 'open' AND lower(trim(a.title)) >= 'metric-trigger-' AND lower(trim(a.title)) < 'metric-trigger.' AND a.title GLOB 'METRIC-TRIGGER-[0-9]*'), up AS (SELECT pi.issue_id AS pid, MIN(CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) AS crank FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = 'disabled-duplicate' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 JOIN oi pi ON pi.tid = pt.id AND pi.issue_id <> c.issue_id GROUP BY pi.issue_id)
UPDATE agent_issues SET priority = CASE (SELECT up.crank FROM up WHERE up.pid = agent_issues.id) WHEN 0 THEN 'critical' WHEN 1 THEN 'high' WHEN 2 THEN 'medium' ELSE 'low' END
WHERE status = 'open' AND id IN (SELECT pid FROM up) AND (CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) > (SELECT up.crank FROM up WHERE up.pid = agent_issues.id);

-- ONE-TIME: the doctor skips an issue whose description carries a code-task line or whose [issue #N] task is not failed/closed/superseded (a merged task counts), so the covered children 99937 and 2570 (tasks
-- ct_7i753c8gmtb38z and ct_im99937 merged 2026-10-19, ct_im2570 closed 2026-10-19) can never be reached by MD-6. The same close is applied to them once, with the same evidence, when no code task of the issue is live.
WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), '-') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = 'open' AND lower(trim(a.title)) >= 'metric-trigger-' AND lower(trim(a.title)) < 'metric-trigger.' AND a.title GLOB 'METRIC-TRIGGER-[0-9]*') INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT c.issue_id, 'breach-doctor:MD-6:migration', 'closed', 'breach-doctor', datetime('now'), 'SUPERSEDED BY #' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) || ': metric trigger ' || c.tid || ' is disabled (enabled=0) and metric_deps relation disabled-duplicate names metric ' || d.parent_metric || ' as the one that keeps its meaning, and the trigger ' || pt.id || ' of that metric is enabled and #' || (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) || ' is open, at least as urgent and carries the work. Closed once by migration 2026-10-26-metric-playbooks (rule MD-6) because the engine reads the code-task line or the merged task in this issue as a doer, and every code task of this issue has ended.' FROM oi c JOIN analytics_metric_triggers ct ON ct.id = c.tid AND ct.enabled = 0 JOIN metric_deps d ON d.child_metric = ct.metric_key AND d.active = 1 AND d.relation = 'disabled-duplicate' JOIN analytics_metric_triggers pt ON pt.metric_key = d.parent_metric AND pt.enabled = 1 WHERE (SELECT MIN(pi.issue_id) FROM oi pi WHERE pi.tid = pt.id AND pi.issue_id <> c.issue_id AND (CASE pi.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END) <= (CASE c.pri WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END)) IS NOT NULL AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = c.issue_id AND xc.status IN ('active','holding') AND COALESCE(xc.last_verdict,'') IN ('fail','vacuous-probe-result','probe-error','probe-not-machine-executable','probe-same-account-host')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = c.issue_id OR xw.path = 'issue:' || c.issue_id) AND xw.released_at IS NULL AND xw.expires_at > strftime('%Y-%m-%dT%H:%M:%SZ','now')) AND c.issue_id IN (SELECT a.id FROM agent_issues a WHERE a.status = 'open' AND instr(COALESCE(a.description, ''), 'code-task:') > 0 AND NOT EXISTS (SELECT 1 FROM code_tasks k WHERE (k.goal LIKE '[issue #' || a.id || ']%' OR k.id = 'ct_im' || a.id) AND k.status NOT IN ('merged', 'failed', 'closed', 'superseded', 'needs_human', 'publish_failed'))) ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = 'closed', owner = 'breach-doctor', close_evidence = excluded.close_evidence;

-- ONE-TIME: issue 99949 (trigger 5916 papers_live_failing_release_gate) is also stranded: the trigger is disabled and has no parent metric (BREACH-ONE-MEANING-1: it contradicts the owner directive of 2026-10-26 06:35,
-- pub-gate-v4-no-withdraw, a weak paper stays live and is revised), and its two code tasks merged on 2026-10-19 and 2026-10-20. The evaluator never reopens the issue of a disabled trigger. Closed with MOOT evidence.
INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence)
SELECT a.id, 'breach-doctor:MD-6:migration', 'closed', 'breach-doctor', datetime('now'),
  'MOOT: metric trigger 5916 (papers_live_failing_release_gate) is disabled (enabled=0) and no metric carries its meaning in metric_deps; BREACH-ONE-MEANING-1 disabled it on 2026-10-26 because it contradicts the owner directive of 2026-10-26 06:35 (pub-gate-v4-no-withdraw: a weak paper stays live and is revised), its code tasks ct_cl1domo3wy60p9 and ct_im99949 merged on 2026-10-19 and 2026-10-20, and the evaluator never reopens the issue of a disabled trigger. Closed once by migration 2026-10-26-metric-playbooks from analytics_metric_triggers and code_tasks facts only.'
FROM agent_issues a
WHERE a.id = 99949 AND a.status = 'open' AND a.title LIKE 'METRIC-TRIGGER-5916-%'
  AND EXISTS (SELECT 1 FROM analytics_metric_triggers t WHERE t.id = 5916 AND t.enabled = 0)
  AND NOT EXISTS (SELECT 1 FROM code_tasks k WHERE k.goal LIKE '[issue #99949]%' AND k.status NOT IN ('merged', 'failed', 'closed', 'superseded', 'needs_human', 'publish_failed'))
  AND NOT EXISTS (SELECT 1 FROM remediation_contracts xc WHERE xc.issue_id = a.id AND xc.status IN ('active','holding') AND COALESCE(xc.last_verdict,'') IN ('fail','vacuous-probe-result','probe-error','probe-not-machine-executable','probe-same-account-host')) AND NOT EXISTS (SELECT 1 FROM work_claims xw WHERE (xw.issue_id = a.id OR xw.path = 'issue:' || a.id) AND xw.released_at IS NULL AND xw.expires_at > strftime('%Y-%m-%dT%H:%M:%SZ','now'))
ON CONFLICT(issue_id) DO UPDATE SET rc = excluded.rc, triage_state = 'closed', owner = 'breach-doctor', close_evidence = excluded.close_evidence;

-- Code levers (ACT-BRIDGE-1): one anchored edit each, in a file the code loop may change (CODE-LOOP-CONTROL-PLANE-1). The code-anchor of each occurs exactly once in qnfo-fleet-control/worker.js on main (read 2026-10-26 11:25Z,
-- count 1 each); the code-probe fails today and passes only when the edit is on main; the d1 contract issue-<id>-outcome is read in addition (the issue closes only when both pass). MD-P1a and MD-P1b have no symptom to measure
-- today (0 duplicate pairs and 0 odd operators, both held at 0 by hand and by BREACH-ONE-MEANING-1), so their outcome contract is the standing guard and the code-probe is what keeps the issue open until the code changes.
-- Single-row VALUES inserts: agent_issues refuses the INSERT ... SELECT shape at compile time on some days (migrations/2026-10-18-issue-sla-guard-reliable.sql); agent_issues_open_dup_annotate makes a replay a no-op.

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P1a qnfo-fleet-control evaluateMetricTriggers dedupes a trigger issue by trigger id, not by the whole title',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-1). evaluateMetricTriggers files METRIC-TRIGGER-<id>-<METRIC>: <title> and looks for an existing issue by the whole title, so a trigger whose title is edited files a second open issue for the same trigger: COST-BUDGET-RECALIBRATION-1 did it to triggers 354 and 409 and a hand-filed METRIC-TRIGGER: breaches_without_ticket did it to trigger 8888 (three pairs open on 2026-10-26 06:35Z: 99924/100226, 99928/100225, 100088/1000015). The playbook MD-1 closes the extra issue after 120 minutes; this change stops it being filed.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js evaluateMetricTriggers replace the lookup on the line after the var title line (SELECT id, status FROM agent_issues WHERE lower(trim(title)) = lower(trim(?1)) AND status IN (''open'',''monitoring'',''closed'') ORDER BY CASE status ...) with a lookup by trigger id: SELECT id, status FROM agent_issues WHERE title LIKE ?1 AND status IN (''open'',''monitoring'',''closed'') ORDER BY CASE status WHEN ''open'' THEN 0 WHEN ''monitoring'' THEN 1 ELSE 2 END, id LIMIT 1, bound to "METRIC-TRIGGER-" + t.id + "-%". Keep the title that is inserted, the reopen branch of a parked twin, the deduped note and the unreadable list as they are. Test: a trigger whose title changes between two ticks files one issue, and its reopen still finds the closed twin.' || char(10) ||
  'Definition of done: the old whole-title lookup is gone from main (the code-probe) and no trigger id has two open issues (the standing d1 contract issue-<id>-outcome, which reads ok today because MD-1 and the manual closes keep it so).' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var title = "METRIC-TRIGGER-" + t.id + "-" + String(t.metric_key).toUpperCase().replace(/[^A-Z0-9]+/g, "-") + ": " + String(t.title || t.action || "").slice(0, 80);' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "absent": "lower(trim(title)) = lower(trim(?1)) AND status IN (''open'',''monitoring'',''closed'')"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P1b qnfo-fleet-control an operator outside gt, gte, lt, lte, eq is unreadable, never read as gte',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-2). evaluateMetricTriggers, ilTriggerHit and perfBreaches read every operator they do not know as gte. A trigger written with ''>'' therefore fired at value 0 against threshold 0 (prd_funnel_monitor_stale and personal_calendar_delivery_over_120m were false breaches until BREACH-ONE-MEANING-1 normalised the symbols in D1 with two triggers and a view); a typo or a new symbol would do it again, in code, where nothing normalises it.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js make the comparison fail closed in all three places that carry the line ... op === "eq" ? v === thr : v >= thr: accept gt, gte, lt, lte, eq and the symbols > >= < <= = ==; a missing or empty operator keeps meaning gte; any other operator in evaluateMetricTriggers pushes t.metric_key to out.unreadable and continues, and in ilTriggerHit and perfBreaches returns false. Every known operator keeps its exact behaviour. Test: operator ''!='' with value 5 and threshold 1 is unreadable and files nothing; ''>'' with value 0 and threshold 0 is not a hit.' || char(10) ||
  'Definition of done: no comparison on main ends in op === "eq" ? v === thr : v >= thr (the code-probe) and no enabled trigger has an operator outside the set (the standing d1 contract issue-<id>-outcome, ok today).' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var hit = op === "gt" ? v > thr : op === "lte" ? v <= thr : op === "lt" ? v < thr : op === "eq" ? v === thr : v >= thr;' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "absent": ": op === \"eq\" ? v === thr : v >= thr;"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P1c qnfo-fleet-control a recovered trigger issue closes after 3 refresh cadences (at most 120 minutes), not after a fixed 60',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-4). TRIGGER-RECOVERY-1 closes a METRIC-TRIGGER issue once its metric has been clear for TRIGGER_RECOVERY_MIN = 60 minutes, and the next hit reopens the closed twin. Measured 2026-10-26 on issue_lifecycle: 165 reopened events in 7 days and 56 in the last 24 h on METRIC-TRIGGER issues; of 146 close-then-reopen pairs in 7 days 33 reopened within 60 minutes and 10 within 120, so 29 percent of the churn is a close that a second hour of clear readings would have withheld. The longer hold of the audit (6 h, 24 h) would keep recovered issues open past 120 minutes (SLA-120M-1, ISSUE-SLA-2H-1), so the hold is capped at 120.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js keep var TRIGGER_RECOVERY_MIN = 60 as the floor and add var TRIGGER_RECOVERY_MAX_MIN = 120 and a pure helper triggerRecoveryHoldMin(refreshCadence) that returns Math.min(TRIGGER_RECOVERY_MAX_MIN, Math.max(TRIGGER_RECOVERY_MIN, 3 x the cadence in minutes)) with the cadence read from metric_registry.refresh_cadence (''10m'' or ''*/10'' 10, ''1h'' or ''hourly'' 60, ''2h'' 120, anything else 60). Use it in the triggerRecoveryDue(streak.t, Date.now(), ...) call of the recovery branch, reading the cadence of t.metric_key once per trigger. A hit during the streak still writes relapsed and ends it. Test: an hourly metric clear for 90 minutes is not closed, at 125 it is; a 10-minute metric closes at 60.' || char(10) ||
  'Definition of done: TRIGGER_RECOVERY_MAX_MIN exists on main (the code-probe) and issue_lifecycle holds at most 40 reopened events in 24 h on METRIC-TRIGGER issues (the d1 contract issue-<id>-outcome, 56 today, a 29 percent cut measured above).' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var TRIGGER_RECOVERY_MIN = 60;' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "TRIGGER_RECOVERY_MAX_MIN"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P2 qnfo-fleet-control the improvement loop does not judge its own output as a regression',
  'Charter pillar: autonomy (ACT-BRIDGE-1, BREACH-DOCTOR-1 rule MD-8). improvementEvaluate files METRIC-REGRESSION-1 for improvement_rate_7d, metric_regressions_7d, fix_hold_rate_30d, fix_target_hold_rate_30d, metrics_in_breach and open_agent_issues: the loop''s own outputs and the headline counts that every other metric issue already feeds. Their week-on-week change is the sum of the other findings, so the issue cannot be fixed on its own and its probe (the latest run still lists it) stays red for good: issues 2323 (metrics_in_breach, 654 failed attempts), 100495 and 100572 are open now.' || char(10) ||
  'Edit: in qnfo-fleet-control/worker.js improvementEvaluate add var IL_SELF_SET = { improvement_rate_7d: 1, metric_regressions_7d: 1, fix_hold_rate_30d: 1, fix_target_hold_rate_30d: 1, metrics_in_breach: 1, open_agent_issues: 1 } beside IL_REGRESS_PCT and, in the registry loop directly above the line var a = ilMean(rec), b = ilMean(pri);, record the metric as a trend with verdict self-set (why: the loop judges its own output; the metric has its own trigger) and return, so it is neither counted as regressed nor filed. The open regression issues then close through the loop''s existing close branch once the finding is gone. Do not change IL_REGRESS_PCT, IL_MIN_POINTS or any other metric''s verdict. Test: a regressed metrics_in_breach files nothing and an open METRIC-REGRESSION-1 issue for it closes; a regressed ordinary metric still files.' || char(10) ||
  'Definition of done: IL_SELF_SET exists on main (the code-probe) and no METRIC-REGRESSION-1 issue for one of the six metrics is open (the d1 contract issue-<id>-outcome, three open today: 2323, 100495, 100572).' || char(10) ||
  'code-task: repo=qnfo-workers path=qnfo-fleet-control/worker.js' || char(10) ||
  'code-anchor: var a = ilMean(rec), b = ilMean(pri);' || char(10) ||
  'code-probe: {"paths": ["qnfo-fleet-control/worker.js"], "contains": "IL_SELF_SET"}',
  'qnfo-fleet-control', 'reliability', 'medium', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) VALUES (
  'BREACH-DOCTOR-1: MD-P4 tick_sequence_completion_24h can exceed 1.0 (hour slots counted against slots due), so a full day reads above target as a miss',
  'Charter pillar: autonomy (BREACH-DOCTOR-1 rule MD-7). tick_sequence_completion_24h = complete hour slots in the last 24 h / MIN(24, hours since the first tick_runs row + 1), written by the D1 trigger tick_driver_roster_tick on fleet_tick (migrations/2026-10-12-21-tick-driver-roster.sql). The numerator counts tick_runs groups of the last 24 h and the denominator is capped at 24, so a day with 25 groups reads 1.042 and metric_history records meets 0 against the target 1.0 (10-19 and 10-21). A ratio of completed to due is at most 1.' || char(10) ||
  'Doer: a session (a D1 trigger on fleet_tick, not worker code, so no code-task line; FLEET-TICK-SPLIT-1 and the 2026-10-18 heartbeat outage are why this is not an auto-merged edit). Change: one migration with APPLY-BY ci, a Rollback line that recreates the trigger from its stored text and a BACKUP table it creates first that holds the trigger definition, which recreates tick_driver_roster_tick with the numerator wrapped as MIN(1.0, ...) and nothing else changed; run /fleet-graph/impact on d1trg:qnfo-audit.tick_driver_roster_tick first and cover what it returns.' || char(10) ||
  'Definition of done: the stored trigger text contains a MIN(1 cap on the ratio (the closing d1 probe of this issue) and metric_history holds no tick_sequence_completion_24h value above 1.0 afterwards.',
  'qnfo-fleet-control', 'reliability', 'low', 'open',
  CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000);

-- The issue-birth trigger gives each row a needs-machine-probe contract; the UPDATE sets the probe the remediation tick runs (code-probe line, PROBE-BIRTH-2), the INSERT OR IGNORE gives a replay and the offline suite the same rows.
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id, id, 'born with the issue (ORPHAN-GUARD-BIRTH-1)', 'needs-machine-probe', 'needs-machine-probe', 'd1-query', 3, 'qnfo-fleet-control', 1, 'needs-machine-probe', 'birth'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P%' AND status = 'open';

UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main; scripts/remediation_consumer.py reads its checkout of main and a pass closes the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "absent": "lower(trim(title)) = lower(trim(?1)) AND status IN (''open'',''monitoring'',''closed'')"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1a %' ORDER BY id DESC LIMIT 1);
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id || '-outcome', id, 'METRIC-PLAYBOOKS-1: the outcome the edit is for', 'the edit lands and the measured outcome holds', 'WITH oi AS (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM oi GROUP BY tid HAVING COUNT(*) > 1) THEN ''a metric trigger has two open issues'' ELSE ''ok'' END AS observed', 'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'metric-playbooks'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1a %' AND status = 'open' ORDER BY id DESC LIMIT 1;

UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main; scripts/remediation_consumer.py reads its checkout of main and a pass closes the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "absent": ": op === \"eq\" ? v === thr : v >= thr;"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1b %' ORDER BY id DESC LIMIT 1);
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id || '-outcome', id, 'METRIC-PLAYBOOKS-1: the outcome the edit is for', 'the edit lands and the measured outcome holds', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM analytics_metric_triggers WHERE enabled = 1 AND trim(operator) NOT IN (''gt'', ''gte'', ''lt'', ''lte'', ''eq'')) THEN ''an enabled trigger has an operator outside the evaluator set'' ELSE ''ok'' END AS observed', 'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'metric-playbooks'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1b %' AND status = 'open' ORDER BY id DESC LIMIT 1;

UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main; scripts/remediation_consumer.py reads its checkout of main and a pass closes the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "contains": "TRIGGER_RECOVERY_MAX_MIN"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1c %' ORDER BY id DESC LIMIT 1);
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id || '-outcome', id, 'METRIC-PLAYBOOKS-1: the outcome the edit is for', 'the edit lands and the measured outcome holds', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT COUNT(*) FROM issue_lifecycle l JOIN agent_issues a ON a.id = l.issue_id WHERE l.event = ''reopened'' AND l.ts > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-24 hours'') AND a.title LIKE ''METRIC-TRIGGER-%'') > 40 THEN ''more than 40 METRIC-TRIGGER issues were reopened in 24 hours'' ELSE ''ok'' END AS observed', 'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'metric-playbooks'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P1c %' AND status = 'open' ORDER BY id DESC LIMIT 1;

UPDATE remediation_contracts SET precondition = 'code-probe line in the issue (PROBE-BIRTH-2)',
  action = 'the doer changes the code on main; scripts/remediation_consumer.py reads its checkout of main and a pass closes the code part of the issue',
  verify_probe = '{"paths": ["qnfo-fleet-control/worker.js"], "contains": "IL_SELF_SET"}',
  verify_transport = 'code-read', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'code-probe-line-v1'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P2 %' ORDER BY id DESC LIMIT 1);
INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module)
SELECT 'issue-' || id || '-outcome', id, 'METRIC-PLAYBOOKS-1: the outcome the edit is for', 'the edit lands and the measured outcome holds', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM agent_issues WHERE status = ''open'' AND (title LIKE ''METRIC-REGRESSION-1: improvement_rate_7d%'' OR title LIKE ''METRIC-REGRESSION-1: metric_regressions_7d%'' OR title LIKE ''METRIC-REGRESSION-1: fix_hold_rate_30d%'' OR title LIKE ''METRIC-REGRESSION-1: fix_target_hold_rate_30d%'' OR title LIKE ''METRIC-REGRESSION-1: metrics_in_breach%'' OR title LIKE ''METRIC-REGRESSION-1: open_agent_issues%'')) THEN ''a METRIC-REGRESSION-1 issue for a self-set metric is open'' ELSE ''ok'' END AS observed', 'd1-query', 1000, 'qnfo-fleet-control', 1, 'active', 'metric-playbooks'
FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P2 %' AND status = 'open' ORDER BY id DESC LIMIT 1;

UPDATE remediation_contracts SET precondition = 'BREACH-DOCTOR-1 rule MD-7: the ratio is written by a D1 trigger on fleet_tick',
  action = 'a session writes the migration after the impact check; the stale-PR lane merges it and CI applies it',
  verify_probe = 'SELECT ''ok'' AS expected, CASE WHEN instr(upper((SELECT sql FROM sqlite_master WHERE type = ''trigger'' AND name = ''tick_driver_roster_tick'')), ''MIN(1'') > 0 THEN ''ok'' ELSE ''the tick_sequence ratio is not capped at 1.0'' END AS observed',
  verify_transport = 'd1-query', max_attempts = 1000, expected_cadence_h = 1, status = 'active', module = 'metric-playbooks'
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title LIKE 'BREACH-DOCTOR-1: MD-P4 %' ORDER BY id DESC LIMIT 1);

-- DOCTRINE-1: the gate MD-4 adds (a recovery streak of 120 minutes before the doctor closes) and the record MD-7 writes (a dated disposition) are registered with their reason, alternate path and a dated review.
INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence) VALUES
 ('metric-playbook-recovery-hold', 'breach_playbooks MD-4 trigger_sql: the recovery streak of analytics_action_log must be 120 minutes old', 'gate', 'the doctor closing a recovered METRIC-TRIGGER issue on a one-reading dip that the evaluator reopens an hour later (56 reopened events in 24 h on 2026-10-26)', 0, 'keep', 'planned',
  'TRIGGER-RECOVERY-1 in evaluateMetricTriggers closes at 60 minutes regardless; the gate only delays the doctor, never the evaluator. breach_playbooks.enabled = 0 for MD-4, or ops_config breach_doctor = off, removes it without a deploy', NULL,
  'recorded reason 2026-10-26: the gate is 120 minutes, the SLA-120M-1 ceiling, and applies to closing only, never to filing or reopening. Expiry: review by 2026-11-02 against doctor_actions_failed_24h and the MD-4 verify failures; no live evidence against it (0 hits on 2026-10-26)'),
 ('metric-playbook-time-gate', 'metric_dispositions rows written by playbook MD-7', 'filter', 'a 24 h heartbeat metric counted as an unowned, undiagnosed breach while one closed fleet_tick gap is still inside its window', 0, 'keep', 'planned',
  'the row expires 25 hours after the gap ended (a margin of an hour) and released_at ends it early; the issue stays open and the evaluator is untouched; fm-metric-disposition-expired reads an expired row whose trigger is still hit, so a wrong replay is seen within the hour', NULL,
  'recorded reason 2026-10-26: replay of fleet_tick (gap 04:32:44Z to 06:06:58Z) explains tick_completion_24h 93.8, tick_slot_coverage_24h 0.937 and tick_sequence_completion_24h 0.792, which clear by 2026-10-27T07:06:58Z. Expiry: review by 2026-11-02 against the first expired disposition; no live evidence against it');

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('metric-disposition-expired', 'a time-gated disposition passed its expiry and the metric is still hit', 'the replay behind MD-7 was wrong (a second gap, or the writer of the metric counts something the heartbeat does not), or the metric moved on a path the replay does not know',
  'the doctor does not renew a disposition: MD-7 fires again only while the newest gap is inside the 24 h window; an expired disposition with a hit trigger leaves the issue to its normal path and fm-metric-disposition-expired files the contract', 'fm-metric-disposition-expired: no expired disposition on a trigger that is still hit', 'fm-metric-disposition-expired', '2026-10-26', 1000266,
  'a metric_dispositions row past expires_at with released_at NULL whose trigger reads hit = 1 and whose issue is open', 'a breach stays open with a dated reason that did not hold', 'the issues MD-7 diagnosed'),
 ('metric-trigger-disabled-issue-open', 'an open METRIC-TRIGGER issue belongs to a disabled trigger', 'a trigger is disabled (a duplicate, a contradicted target) and its open issue is left behind: evaluateMetricTriggers reads enabled = 1 only, so nothing closes or reopens it',
  'add a metric_deps row (relation disabled-duplicate) naming the metric that keeps the meaning and MD-6 supersedes the issue to the parent within the doctor tick; a disabled trigger with no parent is closed with MOOT evidence by the migration that disabled it', 'fm-metric-trigger-disabled-issue-open: no open METRIC-TRIGGER issue older than 120 minutes belongs to a disabled trigger', 'fm-metric-trigger-disabled-issue-open', '2026-10-26', 1000266,
  'an open METRIC-TRIGGER-<id> issue older than 120 minutes whose analytics_metric_triggers row has enabled = 0', 'issues_open_over_120m counts an issue no loop can close', 'the issues of every trigger a migration disables');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, verify_probe, verify_transport, max_attempts, expected_cadence_h, status, precondition, action, escalate_to, module) VALUES
 ('fm-metric-disposition-expired', NULL, 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM metric_dispositions md JOIN v_metric_trigger_state s ON s.id = md.trigger_id JOIN agent_issues a ON a.id = md.issue_id AND a.status = ''open'' WHERE md.released_at IS NULL AND md.expires_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'') AND s.hit = 1) AS TEXT) AS observed', 'd1-query', 3, 1, 'active', 'METRIC-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode'),
 ('fm-metric-trigger-disabled-issue-open', NULL, 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM (SELECT a.id AS issue_id, a.priority AS pri, CAST(substr(a.title, 16, instr(substr(a.title, 16), ''-'') - 1) AS INTEGER) AS tid FROM agent_issues a WHERE a.status = ''open'' AND lower(trim(a.title)) >= ''metric-trigger-'' AND lower(trim(a.title)) < ''metric-trigger.'' AND a.title GLOB ''METRIC-TRIGGER-[0-9]*'') oi JOIN analytics_metric_triggers t ON t.id = oi.tid AND t.enabled = 0 JOIN agent_issues a ON a.id = oi.issue_id WHERE a.created_at < (CAST(strftime(''%s'',''now'') AS INTEGER) - 7200) * 1000 AND EXISTS (SELECT 1 FROM breach_playbooks p WHERE p.rule_id = ''MD-6'' AND p.created_at < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-90 minutes''))) AS TEXT) AS observed', 'd1-query', 3, 1, 'active', 'METRIC-PLAYBOOKS-1', 'failure-mode detector', 'qnfo-fleet-control', 'failure-mode');

INSERT OR IGNORE INTO capability_ledger (capability, provenance, prerequisites, reliability, acquired_at, last_exercised_at, evidence) VALUES
 ('breach-doctor:metric-trigger-playbooks', 'METRIC-PLAYBOOKS-1 (migrations/2026-10-26-metric-playbooks.sql, qnfo-fleet-control 0.53.1)', 'breach doctor engine (0.53.0), breach_playbooks rows MD-1, MD-4, MD-6, MD-7, metric_deps, metric_dispositions', 'unmeasured until the first verified case: breaches_auto_remediated_24h', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL,
  'the fleet supersedes a duplicate or covered METRIC-TRIGGER issue, closes a recovered one the evaluator missed and dates a time-gated heartbeat breach, each with ids, counts and a stored revert, without a session');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session_01QpQv19uh1padRwZ3u1r766',
  'a rule belongs in the doctor only if its trigger_sql names the issues from ids, counts and enum codes and its hits were re-measured live; a rule the audit proposed that the live data refutes (MD-9: the contract is correct and the finding is live) or that BREACH-ONE-MEANING already fixed (MD-2, MD-5) is not built, and an hour-scale hold is capped at 120 minutes (SLA-120M-1)',
  'METRIC-PLAYBOOKS-1: playbooks MD-1 (duplicate trigger issue), MD-4 (recovered but open), MD-6 (covered by the parent metric) and MD-7 (time-gated heartbeat metric); metric_deps and metric_dispositions; a one-time raise of the parents of the covered children (99938 critical, 100301 high) and a one-time close of the three stranded issues 99937, 2570 and 99949; five lever issues (MD-P1a, MD-P1b, MD-P1c, MD-P2, MD-P4) with a code-probe and an outcome contract each',
  'qnfo-audit 2026-10-26 11:30Z: 87 open METRIC-* issues; MD-6 reads 6 hits (100225, 3015, 99914, 99915 reachable, 99937 and 2570 not), MD-7 reads 3 (2875, 99936, 2861; fleet_tick gap ended 06:06:58Z), MD-1 and MD-4 read 0; metric_history and issue_lifecycle give 56 reopened events in 24 h; all anchors occur once in qnfo-fleet-control/worker.js',
  'migration merged; qnfo-fleet-control 0.53.1 deployed through the canonical path (one allowlist const)',
  'issue_triage, agent_issues (close through the close-sync triggers; the priority of three parent issues once, by this file), metric_dispositions, breach_diagnoses; every playbook action is bound to one issue and stores its revert',
  'breach_playbooks.enabled = 0 per rule or ops_config breach_doctor = off; the Rollback header reopens the three issues the file closed once and restores the three priorities from bak_20261026_metric_playbooks_priority; every applied case carries its revert_sql',
  'the fleet diagnoses and clears the duplicate, covered, recovered and time-gated METRIC-TRIGGER issues without a session',
  'breaches_auto_remediated_24h >= 6 within 24 h',
  'none', 'breach_playbooks, metric_deps, metric_dispositions, agent_issues, issue_triage, fleet_tick, analytics_action_log; migrations/metric-playbooks.test.mjs'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'METRIC-PLAYBOOKS-1:%');
